import {seed,compile,match,optimize,fund,completeStop,impact,outstanding,uid,example,money,time,distance,shelter,type Mission,type Resource} from './engine.ts';
const $=(s:string)=>document.querySelector(s) as HTMLElement;
const esc=(s:any)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
let db:any;try{db=JSON.parse(localStorage.getItem('missionmesh-v1')||'null')||seed()}catch{db=seed()}
let role=db.role||'Nonprofit',path=location.pathname,scan:any[]=[],photo='',scanned=false,draft:Mission|null=null,filter='All resources',busy=false;
let map:any=null;const iconPaths:any={mesh:'M5 4h5v5H5z M14 4h5v5h-5z M5 13h5v5H5z M14 13h5v5h-5z M10 6.5h4 M10 15.5h4 M7.5 9v4 M16.5 9v4',home:'m3 10 9-7 9 7 M5 9v12h14V9 M9 21v-8h6v8',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',map:'m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3z M9 3v15 M15 6v15',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',arrow:'M4 12h16 m-6-6 6 6-6 6',plus:'M12 5v14 M5 12h14',check:'m5 12 4 4 10-10',leaf:'M20 3C7 2 2 8 5 16s15 6 15-13Z M5 20l11-12',heart:'M12 21 3 12C-3 4 7-1 12 6c5-7 15-2 9 6z',truck:'M2 5h12v12H2z M14 9h5l3 5v3h-8 M5 17a2 2 0 1 0 0 .1 M18 17a2 2 0 1 0 0 .1',people:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21v-3a7 7 0 0 1 14 0v3 M17 4a4 4 0 0 1 0 7 M18 14a6 6 0 0 1 4 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',chevron:'m9 5 7 7-7 7',camera:'M3 6h4l2-3h6l2 3h4v14H3z M12 9a4 4 0 1 0 0 8 4 4 0 0 0 0-8',box:'m3 7 9-4 9 4-9 5z M3 7v10l9 4 9-4V7 M12 12v9',coin:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M15 8h-4a2 2 0 0 0 0 4h2a2 2 0 0 1 0 4H9 M12 6v12',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5z M10 21h4',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',reset:'M4 10a8 8 0 1 1 2 8 M4 3v7h7'};
const I=(name:string,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.box}"/></svg>`;
const a=(p:string,label:string,cls='')=>`<a href="${p}" data-nav="${p}" class="${cls}">${label}</a>`;
const btn=(label:string,action:string,cls='primary',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const badge=(s:string,cls='')=>`<span class="badge ${cls}">${esc(s)}</span>`;
function save(){db.role=role;try{localStorage.setItem('missionmesh-v1',JSON.stringify(db))}catch{toast('Browser storage is full. Your current session is still available.')} }
function toast(s:string){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function go(p:string){path=p;history.pushState({},'',p);window.scrollTo(0,0);render()}
window.onpopstate=()=>{path=location.pathname;render()};window.addEventListener('storage',e=>{if(e.key==='missionmesh-v1'){try{db=JSON.parse(e.newValue!);render()}catch{}}});
const current=()=>{const id=path.startsWith('/volunteer/route/')?path.split('/')[3]:path.startsWith('/mission/')?path.split('/')[2]:null;return id?db.missions.find((m:Mission)=>m.id===id):db.missions[db.missions.length-1]};
const total=(key:string)=>db.impactRecords.reduce((s:number,i:any)=>s+(i[key]||0),0);
function title(kicker:string,heading:string,description:string,cta=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${heading}</h1><p>${description}</p></div>${cta}</div>`}
function shell(body:string,landing=false){const baseRole=path.startsWith('/business')?'Business':path.startsWith('/nonprofit')?'Nonprofit':path.startsWith('/volunteer')?'Volunteer':path.startsWith('/sponsor')?'Sponsor':role;const nav=[['grid',`/${baseRole.toLowerCase()}`,'Overview'],['spark','/nonprofit/create','Mission compiler'],['map','/explore','Community map'],['heart','/impact','Our impact']];return `<div class="layout ${landing?'landing-layout':''}"><aside class="sidebar">${a('/',`${I('mesh',30)}<span>MISSION<span class="brand-light">MESH</span></span>`,'brand')}<div class="workspace"><div class="workspace-icon">H</div><div><strong>Atlanta community</strong><small>Connected for good</small></div><span class="online-dot"></span></div><div class="nav-caption">WORKSPACE</div><nav>${nav.map(([i,p,l])=>a(p,`${I(i)}<span>${l}</span>${i==='spark'?'<span class="tiny-label">AI</span>':''}`,`nav-link ${path===p?'active':''}`)).join('')}${a('/how-it-works',`${I('people')}<span>How it works</span>`,`nav-link ${path==='/how-it-works'?'active':''}`)}</nav><div class="sidebar-bottom"><div class="community-note"><span>${I('leaf')}</span><strong>A little surplus.<br>A lot of possibility.</strong><p>Your next contribution could be someone's next meal.</p>${a('/business/quick-give','Share a resource '+I('arrow'),'note-link')}</div>${btn(I('reset',16)+' Reset demo','reset','text')}<div class="profile"><div class="avatar">VP</div><div><strong>Demo workspace</strong><small>All four roles unlocked</small></div>${I('chevron',16)}</div></div></aside><div class="main-wrap"><header class="topbar"><div class="crumb">${I('mesh',16)} <span>Atlanta, GA</span><span class="divider">/</span><strong>${landing?'Community, coordinated':baseRole+' workspace'}</strong></div><div class="top-actions"><span class="demo-dot">Demo mode</span><div class="role-switch" aria-label="Demo role switcher">${['Business','Nonprofit','Volunteer','Sponsor'].map(r=>`<button data-role="${r}" class="${baseRole===r?'selected':''}">${r}</button>`).join('')}</div></div></header><main>${body}<footer>MISSIONMESH <span>Tell us the outcome. AI assembles the community.</span><span>Atlanta demo · Local browser persistence</span></footer></main></div><nav class="mobile-nav">${nav.map(([i,p,l])=>a(p,`${I(i)}<span>${l==='Mission compiler'?'Create':l==='Community map'?'Explore':l==='Our impact'?'Impact':l}</span>`,path===p?'active':'')).join('')}</nav></div>`}
function stat(icon:string,value:string,label:string,note:string='',cls=''){return `<div class="stat ${cls}"><div class="stat-top"><span class="icon-tile">${I(icon)}</span>${note?`<small>${note}</small>`:''}</div><strong>${value}</strong><span>${label}</span></div>`}
function landing(){return shell(`<section class="landing-hero"><div class="hero-copy"><div class="eyebrow light">COMMUNITY RESOURCES. REAL OUTCOMES.</div><h1>One mission.<br>A whole community<br><em>behind it.</em></h1><p>Tell us the outcome. AI assembles the community.<br>Turn unused food, goods, time, and funding into a plan that gets good done.</p><div class="actions">${a('/nonprofit/create','Create a Mission '+I('arrow'),'btn primary')}${a('/business/quick-give','Donate Surplus','btn white-outline')}</div><div class="hero-bottom">${btn('Run Demo '+I('spark',16),'run-demo','light')}<span>From surplus to supper, in minutes.</span></div></div><div class="mission-illustration"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="floating mini-donor one">${I('box')}<div><strong>40 meals</strong><small>Sunrise Restaurant</small></div><b>✓</b></div><div class="floating mini-donor two">${I('leaf')}<div><strong>Fresh produce</strong><small>FreshMart Grocery</small></div><b>✓</b></div><div class="center-mission">${I('mesh',40)}<small>ONE SHARED MISSION</small><h3>Dinner for<br>100 people</h3><span class="badge mint">95% community covered</span></div><div class="floating mini-donor three">${I('truck')}<div><strong>Alex is on the way</strong><small>Volunteer · SUV</small></div><b>✓</b></div><div class="floating gap-card"><small>THE ONLY THING MISSING</small><strong><s>$612</s> ${I('arrow')} $28</strong><span>A little funding. A complete mission.</span></div><span class="hero-sprout">✳</span></div></section><div class="stats-grid five">${stat('people','2,480','Meals rescued')}${stat('coin','$18,420','Resources redirected')}${stat('check','142','Missions completed')}${stat('heart','61','Local partners')}${stat('leaf','8,900 lbs','Waste prevented')}</div><section class="section"><div class="section-head"><div><div class="eyebrow">THE MISSION COMPILER</div><h2>A better way to get good done.</h2></div>${a('/how-it-works','See how it works '+I('arrow'),'subtle-link')}</div><div class="workflow">${[['box','01','Share what’s spare','Businesses post resources in seconds.'],['spark','02','Name the outcome','Nonprofits describe what needs to happen.'],['mesh','03','Assemble the community','AI drafts a plan; you review every match.'],['truck','04','Deliver with purpose','Volunteers turn a route into real help.'],['coin','05','Close just the gap','Sponsors fund only what’s missing.']].map(([i,n,h,p])=>`<div><span class="step-icon">${I(i,26)}</span><small>${n}</small><h3>${h}</h3><p>${p}</p></div>`).join('')}</div></section><section class="role-cards">${[['Business','box','Your surplus has a purpose.','Less waste. More local impact.'],['Nonprofit','spark','Start with the outcome.','One goal, one coordinated community.'],['Volunteer','truck','Make the last mile matter.','Your time delivers something meaningful.']].map(([r,i,h,p])=>a('/'+r.toLowerCase(),`<span class="icon-tile">${I(i)}</span><div class="eyebrow">FOR ${r.toUpperCase()}${r==='Business'?'ES':'S'}</div><h3>${h}</h3><p>${p}</p><span>Enter workspace ${I('arrow')}</span>`,'role-card')).join('')}</section>`,true)}
function missionCard(m:Mission){const covered=m.originalCost?Math.round(m.communityValue/m.originalCost*100):0;return `<article class="mission-card"><div class="mission-cover"><div class="mission-cover-art">${I('people',54)}<span class="cover-leaf">${I('leaf',60)}</span><span class="cover-box">${I('box',44)}</span></div>${badge(m.status==='Completed'?'Completed':m.status==='Draft'?'Planning':m.status,'mint')}</div><div class="mission-card-body"><div class="meta">COMMUNITY MEALS <span>Today</span></div><h3>${esc(m.title)}</h3><p>${I('map',15)} Hope Community Shelter</p><div class="mission-detail"><span>${I('clock',15)} By ${time(m.deadline)}</span><span>${I('people',15)} ${m.people} people</span></div><div class="progress-label"><span>Community coverage</span><strong>${covered}%</strong></div><div class="progress"><i style="width:${covered}%"></i></div><div class="mission-card-foot"><div class="partner-avatars"><span>S</span><span>F</span><span>C</span><span>+1</span></div>${a(`/mission/${m.id}/${m.status==='Completed'?'impact':m.status==='In progress'?'live':m.matches.length?'plan':'plan'}`,'View mission '+I('arrow',16),'subtle-link')}</div></div></article>`}
function nonprofit(){const active=db.missions.filter((m:Mission)=>m.status!=='Completed');return shell(`${title('NONPROFIT WORKSPACE','Good afternoon, Hope Shelter <span class="wave">☀</span>','Big things happen when the community comes together.',a('/nonprofit/create',I('plus')+' Create Mission','btn primary'))}<div class="stats-grid">${stat('spark',String(active.length),'Active missions','In motion')}${stat('check',String(24+db.impactRecords.length),'Completed missions','↑ 4 this month')}${stat('box',money(8460+total('estimatedValueSaved')),'Community resources used','Value put to work')}${stat('coin',money(7290+total('estimatedValueSaved')),'Money saved','↑ 18% this month')}</div><section class="compiler-banner"><div class="compiler-icon">${I('spark',33)}</div><div><span class="eyebrow">YOUR GOAL. OUR CONNECTIONS.</span><h2>What does your community need today?</h2><p>Describe the outcome. We’ll find the resources, people, and path to make it happen.</p></div>${a('/nonprofit/create','Build a mission '+I('arrow'),'btn purple')}</section><section class="section"><div class="section-head"><div><h2>Your missions <span class="count">${db.missions.length}</span></h2><p>From a good idea to a real-world outcome.</p></div><div class="tabs">${btn('Active','tab-active','text selected')}${btn('Completed','tab-completed','text')}</div></div><div class="missions-grid" id="mission-list">${(active.length?active.map(missionCard).join(''):'<div class="empty">Create your first community mission.</div>')}<a href="/nonprofit/create" data-nav="/nonprofit/create" class="create-card"><span>${I('plus',28)}</span><h3>Good starts with a goal.</h3><p>What could your community<br>make possible together?</p><strong>Create a new mission ${I('arrow',16)}</strong></a></div></section><section class="resources-section"><div class="section-head"><div><h2>Good things, close by.</h2><p>Fresh resources ready for a purpose.</p></div>${a('/explore','Explore community '+I('arrow'),'subtle-link')}</div><div class="resource-row">${db.resources.filter((r:Resource)=>r.status==='Available'&&['meal','drink'].includes(r.category)).slice(0,3).map(resourceCard).join('')}</div></section><div class="bottom-callout">${I('leaf',30)}<p>Your community already has more than you think.<br><strong>Let’s put it to work.</strong></p><span>61 local partners. One shared purpose.</span></div>`)}
function resourceCard(r:Resource){return `<article class="resource-card"><span class="resource-icon ${r.category}">${I(r.category==='meal'?'leaf':r.category==='transportation'?'truck':r.category==='drink'?'box':'people',28)}</span><div><small>${esc(r.provider)}</small><h3>${esc(r.name)}</h3><p>${r.quantity} ${esc(r.unit)} <span>·</span> ${distance(r,shelter).toFixed(1)} mi away</p><span class="availability">${I('clock',13)} Until ${time(r.availableUntil)}</span></div><span class="free">FREE</span></article>`}
function business(){const own=db.resources.filter((r:Resource)=>r.organizationId==='org-sunrise');return shell(`${title('BUSINESS WORKSPACE','Good afternoon, Sunrise Restaurant','A little left over can go a long way.',a('/business/quick-give',I('plus')+' Quick Give','btn primary'))}<div class="stats-grid">${stat('leaf',`${420+total('foodWeight')} lbs`,'Food rescued')}${stat('people',String(310+total('peopleServed')),'Meals provided')}${stat('coin',money(2480+total('estimatedValueSaved')),'Estimated value donated')}${stat('heart','8','Nonprofit partners')}</div><section class="compiler-banner"><div class="compiler-icon">${I('camera',32)}</div><div><span class="eyebrow">LESS TYPING. MORE GIVING.</span><h2>One photo can start something good.</h2><p>AI drafts your surplus listing. You confirm the details.</p></div>${a('/business/quick-give','Scan your surplus '+I('arrow'),'btn purple')}</section><div class="section-head"><h2>Active donations <span class="count">${own.filter((r:Resource)=>!['Delivered','Collected'].includes(r.status)).length}</span></h2>${badge('Atlanta community','mint')}</div><div class="donation-list">${own.filter((r:Resource)=>r.status!=='Delivered').map((r:Resource)=>`<article class="donation-row"><span class="resource-icon">${I('box',30)}</span><div><h3>${esc(r.name)}</h3><p>${r.quantity} ${esc(r.unit)} · ${r.storageType}</p></div><div><small>PICKUP DEADLINE</small><strong>${time(r.availableUntil)}</strong></div><div>${badge(r.status,'mint')}<p>${r.status==='Available'?'Ready to match':'Hope Community Shelter'}</p></div></article>`).join('')||'<div class="empty">Nothing active right now. Have surplus to share?</div>'}</div><section class="section"><div class="section-head"><h2>Previous donations</h2></div><div class="donation-list">${own.filter((r:Resource)=>r.status==='Delivered').map(resourceCard).join('')||`<div class="donation-row"><span class="resource-icon">${I('check')}</span><div><h3>28 prepared lunch portions</h3><p>Delivered to Hope Shelter · Previous demo record</p></div>${badge('Delivered','mint')}<strong>$224 put to work</strong></div>`}</div></section>`)}
function quickGive(){return shell(`${title('QUICK GIVE','Good food deserves a second chapter.','Take a photo of what you have left. We’ll help you turn it into a donation.')}<div class="form-layout"><section class="panel"><div class="step-heading"><span>1</span><div><h2>Show us your surplus</h2><p>Upload an image or use your camera.</p></div>${badge('Vision demo','lavender')}</div><label class="upload" for="photo">${photo?`<img src="${esc(photo)}" alt="Selected surplus image">`:`<span class="upload-icon">${I('camera',38)}</span><h3>A photo. A fresh possibility.</h3><p>Drag & drop, or choose an image</p><span class="btn outline">Choose image</span><small>JPG, PNG or WebP · up to 5 MB</small>`}<input type="file" id="photo" accept="image/*" capture="environment" hidden></label><div class="actions">${btn('Use sample surplus','sample','outline')}${photo?btn(I('spark')+' Analyze image','scan','purple'):''}</div>${scanned?`<div class="analysis-head"><div>${I('spark')} <strong>AI suggested — please confirm</strong></div>${badge('Gemini-ready · demo fallback','lavender')}</div><p class="helper">Seeded suggestions for the sample. Live Gemini is not connected; uploaded images receive editable demo suggestions.</p><div id="scan-items">${scan.map((x,i)=>`<div class="scan-row"><label>Item<input data-item="${i}" data-key="name" value="${esc(x.name)}" required></label><label>Qty<input type="number" min="1" data-item="${i}" data-key="quantity" value="${x.quantity}"></label><label>Unit<input data-item="${i}" data-key="unit" value="${esc(x.unit)}"></label><label>Category<select data-item="${i}" data-key="category">${['meal','drink','supplies','space','transportation'].map(c=>`<option ${x.category===c?'selected':''}>${c}</option>`).join('')}</select></label><button class="remove" data-remove="${i}" aria-label="Remove ${esc(x.name)}">×</button></div>`).join('')}</div>${btn(I('plus',16)+' Add item','add-item','text')}`:''}</section><section class="panel"><div class="step-heading"><span>2</span><div><h2>Confirm the details</h2><p>You know your food best.</p></div></div><form id="donation-form"><label>Available until<input name="until" type="time" value="18:00" required></label><label>Pickup address<input name="address" value="675 Ponce de Leon Ave NE, Atlanta, GA" required></label><label>Storage requirement<select name="storage"><option>Refrigerated</option><option>Room temperature</option><option>Frozen</option></select></label><fieldset><legend>Dietary information · confirm what applies</legend><div class="checks">${['Vegetarian','Vegan','Halal','Gluten Free','Contains Nuts','Other'].map(x=>`<label><input type="checkbox" name="diet" value="${x}"> ${x}</label>`).join('')}</div></fieldset><label>Allergens & handling notes<textarea name="notes" placeholder="Ingredients, known allergens, packaging, pickup instructions…" required></textarea></label><label class="check-confirm"><input type="checkbox" name="confirm" required> <span>I confirm quantity, allergens, storage, pickup deadline, and that this food has been stored and handled appropriately.</span></label><div class="safety">${I('heart',18)}<p>AI identifies items and estimates quantity. The donor is responsible for confirming quantity, allergens, storage conditions, and food safety. MissionMesh does not determine whether food is safe to consume.</p></div><button class="btn primary full" ${!scanned?'disabled':''}>Confirm & Post Donation ${I('arrow')}</button></form></section></div>`)}
function createMission(){return shell(`${title('AI MISSION COMPILER','Start with what you want to make possible.','Your community may already have what it takes. Tell us the outcome.')}<div class="create-layout"><section class="panel mission-input"><div class="ai-header">${I('spark',26)}<h2>What outcome are you trying to accomplish?</h2></div><form id="mission-form"><label class="sr-only" for="goal">Mission outcome</label><textarea id="goal" name="goal" rows="5" placeholder="${example}" required>${example}</textarea><div class="examples"><small>TRY A GOAL</small>${btn('Dinner for 100','example-food','chip')}${btn('School supplies for 40','example-supply','chip')}</div><div class="field-grid"><label>Mission location<input name="address" value="${shelter.address}" required></label><label>Maximum budget ($)<input name="budget" type="number" min="0" placeholder="From your goal"></label><label>Deadline<input name="deadline" type="time"></label></div><button class="btn purple full">${I('spark')} Build My Mission ${I('arrow')}</button><p class="helper center">Demo compiler extracts quantities, budget, deadline, and storage. You approve the plan.</p></form></section><aside class="mission-aside"><span class="eyebrow">FROM OUTCOME TO ACTION</span><h2>One goal.<br>Many possibilities.</h2>${[['spark','Understand your goal','Turn your words into clear requirements.'],['box','Find what’s already here','Match resources by need, distance, and availability.'],['truck','Make it happen','Coordinate pickups and fund only the gap.']].map(([i,h,p])=>`<div>${I(i,24)}<section><h3>${h}</h3><p>${p}</p></section></div>`).join('')}<div class="aside-quote">“Tell us the outcome.<br>AI assembles the community.”</div></aside></div>${draft?requirementsForm(draft):''}`)}
function requirementsForm(m:Mission){return `<section class="panel requirements" id="requirements"><div class="section-head"><div><span class="eyebrow">AI DRAFT · HUMAN APPROVAL</span><h2>Here’s what your mission needs.</h2><p>Review and edit before searching community resources.</p></div>${badge('Ready for your review','lavender')}</div><form id="requirements-form"><div class="field-grid"><label>Mission title<input name="title" value="${esc(m.title)}" required></label><label>People served<input name="people" type="number" min="1" max="10000" value="${m.people}" required></label><label>Budget ($)<input name="budget" type="number" min="0" value="${m.budget}" required></label><label>Deadline<input name="deadline" type="time" value="${String(Math.floor(m.deadline/60)).padStart(2,'0')}:${String(m.deadline%60).padStart(2,'0')}" required></label></div><label>Delivery address<input name="address" value="${esc(m.address)}" required></label><div class="requirement-list">${m.requirements.map((r,i)=>`<div>${I(r.category==='transportation'?'truck':'box')}<strong>${esc(r.category)}</strong><input aria-label="${r.category} quantity" name="quantity-${i}" type="number" min="1" value="${r.quantity}" required><span>${r.unit} · ${r.priority}</span></div>`).join('')}</div><label class="check-confirm"><input type="checkbox" name="fridge" ${m.refrigeration?'checked':''}> Refrigeration available at the delivery location</label><fieldset><legend>Dietary requirements</legend><div class="checks">${['Vegetarian','Vegan','Halal','Gluten Free'].map(t=>`<label><input type="checkbox" name="diet" value="${t}" ${m.dietaryTags.includes(t)?'checked':''}> ${t}</label>`).join('')}</div></fieldset><button class="btn purple">Find Community Resources ${I('arrow')}</button></form></section>`}
function steps(m:Mission,stage:number){return `<div class="mission-steps">${['Requirements','Community cart','Close the gap','Delivery plan','Impact'].map((x,i)=>`<span class="${i===stage?'current':i<stage?'done':''}"><b>${i<stage?'✓':i+1}</b>${x}</span>`).join('')}</div>`}
function plan(){const m=current();if(!m)return createMission();if(!m.matches.length&&m.status==='Draft'){match(m,db.resources,db.volunteers[0]);save()}const needed=m.requirements.map((r:any)=>({...r,got:m.matches.filter(x=>x.category===r.category).reduce((s,x)=>s+x.fulfilledQuantity,0)}));return shell(`${steps(m,1)}${title('AI COMMUNITY CART','Your mission. Assembled.','The right resources, connected to the right outcome.',badge('Deterministic matching','lavender'))}<div class="plan-layout"><section><div class="panel goal-summary"><span class="icon-tile">${I('people',26)}</span><div><h2>${esc(m.title)}</h2><p>${esc(m.address)} · By ${time(m.deadline)} · Budget ${money(m.budget)}</p></div></div>${btn('Edit requirements','edit-mission','outline',m.contributions.length?'disabled':'')}<div class="match-list" style="margin-top:18px">${m.matches.map(x=>{const r=db.resources.find((r:Resource)=>r.id===x.resourceId);return `<article class="match-card"><div class="match-card-top"><span class="resource-icon ${r.category}">${I(r.category==='transportation'?'truck':r.category==='meal'?'leaf':'box',28)}</span><div><h3>${esc(r.provider)}</h3><p>${esc(r.name)} · ${x.allocatedQuantity} ${esc(r.unit)}</p></div><strong class="free">FREE</strong></div><div class="match-meta"><span>${I('map',14)} ${distance(r,m).toFixed(1)} mi</span><span>${I('clock',14)} Until ${time(r.availableUntil)}</span>${badge(r.category==='transportation'?'Volunteer available':'Matched','mint')}<span class="score">${x.matchScore}% fit</span></div><p class="match-reason">${I('spark',16)} ${esc(x.reason)}</p></article>`}).join('')||'<div class="empty">We found no complete match yet. Try fewer restrictions, adjust the deadline, or invite local donors.</div>'}</div><div class="safety">${I('heart',18)}<p>Food matches describe fit and availability. Donors and nonprofits must verify handling, allergens, and storage before accepting food.</p></div></section><aside><div class="panel cost-panel"><span class="eyebrow">THE POWER OF COMMUNITY</span><h2>A whole lot more.<br>For a whole lot less.</h2><div class="cost-line"><span>Estimated original cost</span><s>${money(m.originalCost)}</s></div><div class="cost-line green"><span>Covered by community</span><strong>−${money(m.communityValue)}</strong></div><div class="gap-total"><span>Remaining funding gap</span><strong>${money(outstanding(m))}</strong><small>${m.originalCost?Math.round(m.communityValue/m.originalCost*100):0}% covered by existing resources</small></div><div class="coverage"><h3>Resource coverage</h3>${needed.map((r:any)=>`<div class="progress-label"><span>${r.category}</span><strong>${Math.round(r.got)} / ${r.quantity}</strong></div><div class="progress ${r.got<r.quantity?'purple-bar':''}"><i style="width:${Math.min(100,r.got/r.quantity*100)}%"></i></div>`).join('')}</div>${a(`/mission/${m.id}/fund`,'Review Plan & Fund Gap '+I('arrow',18),'btn primary full')}<p class="helper center">You review the plan before any funding.</p></div><div class="route-note">${I('spark',22)}<div><h3>Why these matches?</h3><p>Category and availability are required. Distance, quantity, pickup urgency, dietary needs, and storage determine fit. Bakery portions supplement meals; shelter refills complete drinks.</p></div></div></aside></div>`)}
function funding(){const m=current();if(!m)return createMission();const left=outstanding(m);const miss=m.requirements.filter((r:any)=>r.category!=='transportation').map((r:any)=>({...r,missing:Math.max(0,r.quantity-m.matches.filter(x=>x.category===r.category).reduce((s,x)=>s+x.fulfilledQuantity,0))})).filter((x:any)=>x.missing>0);return shell(`${steps(m,2)}${title('CLOSE THE GAP',left?'So close. Let’s make it whole.':'Funding complete. Possibility unlocked.',esc(m.title))}<div class="fund-layout"><section class="panel funding-card"><div class="fund-circle">${I(left?'heart':'check',45)}</div><span class="eyebrow">${Math.round((m.originalCost-left)/(m.originalCost||1)*100)}% FINANCIALLY RESOURCED</span><h2>${left?'A small contribution.<br>A complete mission.':'This mission now has<br>everything required.'}</h2><p>Your community contributed ${money(m.communityValue)} in resources.<br>${miss.map((x:any)=>`${Math.ceil(x.missing)} additional ${x.category==='meal'?'meal portions':x.unit}`).join(', ')||'The resource requirements are covered.'}${left?' is what’s left to fund.':''}</p><div class="fund-amount">${money(left)}</div><span class="helper">${left?'Remaining gap':'Fully funded · simulated contributions'}</span>${left?`<form id="fund-form"><label>Sponsor name<input name="sponsor" placeholder="Your name or organization" value="Community sponsor" required></label><div class="fund-options">${[5,10,20].map(v=>btn(money(v),'fund-'+v,'outline','type="button"')).join('')}</div><label>Custom contribution ($)<input id="fund-custom" name="amount" type="number" min="0.01" max="${left}" step="0.01" value="${left}" required></label><label class="check-confirm"><input name="approve" type="checkbox" required> I have reviewed the plan and approve a simulated contribution.</label><button class="btn primary full">Fund Full Gap — ${money(left)} ${I('arrow',18)}</button></form>`:a(`/mission/${m.id}/dispatch`,'Generate Delivery Plan '+I('arrow'),'btn primary full')}<p class="simulation-label">${I('coin',15)} Demo payments only · no money is charged</p></section><aside><section class="panel"><h2>Every dollar has a destination.</h2><div class="fund-breakdown"><div><span>Community resource value</span><strong>${money(m.communityValue)}</strong></div><div><span>Additional supplies estimate</span><strong>${money(m.gap)}</strong></div><div><span>Contributed so far</span><strong>${money(m.gap-left)}</strong></div><div><span>Nonprofit budget available</span><strong>${money(m.budget)}</strong></div></div><p class="helper">The budget is a limit, not a payment. Donations are reserved when the funded route starts. Contributions above the gap are capped.</p></section><section class="panel contributions"><h3>A community, coming together.</h3>${m.contributions.map(x=>`<div>${I('heart',18)}<span>${esc(x.sponsorName)}<small>Simulated contribution</small></span><strong>${money(x.amount)}</strong></div>`).join('')||'<p>Be the first to help finish this mission.</p>'}</section></aside></div>`)}
function mapPanel(stops:any[],cls=''){return `<div class="map-panel ${cls}" id="mission-map"><div class="map-fallback"><svg viewBox="0 0 600 470" role="img" aria-label="Schematic map of Atlanta route"><defs><pattern id="streets" width="70" height="60" patternUnits="userSpaceOnUse"><path d="M0 20H70 M30 0V60" stroke="#fff" stroke-width="9"/><path d="M0 20H70 M30 0V60" stroke="#dce4d9" stroke-width="1"/></pattern></defs><rect width="600" height="470" fill="#e9efe4"/><rect width="600" height="470" fill="url(#streets)"/><path d="M450 0q-100 160 50 300t-50 170" stroke="#c9dfd5" stroke-width="45" fill="none"/><text x="230" y="445" fill="#879b8b" font-size="18">ATLANTA</text>${stops.length?`<polyline points="${stops.map((x,i)=>`${90+(i%3)*180},${80+Math.floor(i/3)*175+(i%2)*40}`).join(' ')}" fill="none" stroke="#208665" stroke-width="5" stroke-dasharray="8 4"/>${stops.map((x,i)=>`<g transform="translate(${90+(i%3)*180},${80+Math.floor(i/3)*175+(i%2)*40})"><circle r="19" fill="${x.completedAt?'#8ab29a':'#176b54'}" stroke="white" stroke-width="4"/><text fill="white" text-anchor="middle" y="6" font-size="18">${i+1}</text><text x="-30" y="-30" fill="#365d4c" font-size="12">${esc(x.provider)}</text></g>`).join('')}`:''}</svg><span class="map-label">${badge('Offline map fallback','mint')} Schematic · use addresses for navigation</span></div></div>`}
function dispatch(){const m=current();if(!m)return createMission();return shell(`${steps(m,3)}${title('DELIVERY PLAN','Good things are on the way.','A nearest-neighbor route connects your pickups to the final delivery.',a(`/mission/${m.id}/live`,'Live tracking '+I('arrow'),'btn outline'))}<div class="dispatch-layout"><section>${mapPanel(m.route)}<div class="route-metrics">${stat('map',`${m.distance} mi`,'Estimated road distance')}${stat('clock',`${m.duration} min`,'Estimated duration')}${stat('box',String(m.route.length),'Total stops')}</div><p class="helper">Travel estimates use straight-line distance × 1.35 at 20 mph, plus handling time. Confirm traffic, pickup windows, and handling needs before departure.</p></section><aside class="panel"><span class="eyebrow">YOUR DELIVERY CREW</span><div class="volunteer-person"><div class="avatar large">AM</div><div><h2>${esc(db.volunteers[0].name)}</h2><p>${esc(db.volunteers[0].vehicleType)} · ${esc(db.volunteers[0].capacity)} capacity</p></div></div><label>Assigned volunteer<select id="assign-volunteer"><option>Alex Morgan</option><option ${m.manualPickup?'selected':''}>Manual pickup by nonprofit</option></select></label><div class="route-stop-list">${m.route.map((s:any,i:number)=>`<div><b>${i+1}</b><section><strong>${esc(s.provider)}</strong><p>${esc(s.name)}</p><small>${time(s.scheduledTime)}</small></section>${s.completedAt?I('check',18):''}</div>`).join('')}</div><div class="deadline-note">${I('clock',18)} Mission deadline: ${time(m.deadline)}</div>${outstanding(m)>0?a(`/mission/${m.id}/fund`,'Fund remaining gap first','btn primary full'):btn(m.status==='Completed'?'View completed mission':'Accept & Start Route '+I('arrow'),'start-route','primary full',m.route.at(-1)?.scheduledTime>m.deadline?'disabled':'')} ${m.route.at(-1)?.scheduledTime>m.deadline?'<p class="safety">Route cannot finish by the deadline. Edit the mission deadline before dispatch.</p>':''}</aside></div>`)}
function volunteer(){const v=db.volunteers[0];const missions=db.missions.filter((m:Mission)=>m.status!=='Draft'&&m.status!=='Completed');return shell(`${title('VOLUNTEER WORKSPACE','A few miles. A big difference.','Your time connects good intentions to real outcomes.')}<div class="volunteer-layout"><section class="panel"><h2>Your availability</h2><form id="volunteer-form"><label>Name<input name="name" value="${esc(v.name)}" required></label><label>Vehicle<select name="vehicle">${['SUV','Car','Van','Bicycle'].map(x=>`<option ${v.vehicleType===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Carrying capacity<select name="capacity">${['Large','Medium','Small'].map(x=>`<option ${v.capacity===x?'selected':''}>${x}</option>`).join('')}</select></label><div class="field-grid"><label>Available from<input name="from" type="time" value="${String(Math.floor(v.availableFrom/60)).padStart(2,'0')}:${String(v.availableFrom%60).padStart(2,'0')}" required></label><label>Available until<input name="until" type="time" value="${String(Math.floor(v.availableUntil/60)).padStart(2,'0')}:${String(v.availableUntil%60).padStart(2,'0')}" required></label></div><button class="btn primary full">Save Availability</button></form></section><section><div class="section-head"><h2>Nearby missions</h2>${badge(`${missions.length} ready to help`,'mint')}</div>${missions.map((m:Mission)=>`<article class="panel nearby-mission"><span class="eyebrow">${esc(m.status.toUpperCase())}</span><h2>${esc(m.title)}</h2><p>${m.route.length} stops · ${m.distance} estimated miles · By ${time(m.deadline)}</p>${outstanding(m)?a(`/mission/${m.id}/fund`,'View funding gap','btn outline'):a(`/mission/${m.id}/dispatch`,'Review & accept route '+I('arrow'),'btn primary')}</article>`).join('')||'<div class="empty">No routes available yet. Build a mission to connect the community.</div>'}</section></div>`)}
function routeView(){const m=current();if(!m)return volunteer();const i=m.route.findIndex(x=>!x.completedAt),s=m.route[i];if(m.status==='Completed')return impactPage();return shell(`${title('VOLUNTEER ROUTE','Tonight’s mission',`Help deliver dinner for ${m.people} people.`,a(`/mission/${m.id}/live`,'Live mission','btn outline'))}<div class="mobile-route panel"><div class="progress-label"><strong>${i<0?0:i} of ${m.route.length} stops complete</strong>${badge('In progress','mint')}</div><div class="progress"><i style="width:${i/m.route.length*100}%"></i></div>${s?`<span class="eyebrow">STOP ${i+1} OF ${m.route.length} · ${s.resourceId?'PICKUP':'FINAL DELIVERY'}</span><div class="route-main-icon">${I(s.resourceId?'box':'heart',50)}</div><h2>${esc(s.provider)}</h2><p>${esc(s.address)}</p><div class="pickup-detail"><span>${s.resourceId?'PICKUP':'DELIVER'}</span><strong>${esc(s.name)}</strong><p>Scheduled arrival ${time(s.scheduledTime)}</p>${!s.resourceId?`<p>Includes additional funded supplies (${money(m.gap)}). Their purchase is simulated in this demo.</p>`:''}</div><a href="https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(s.address)}" target="_blank" rel="noopener" class="btn outline full">${I('map')} Navigate</a>${btn(s.resourceId?'Mark Pickup Complete '+I('check'):'Complete Delivery '+I('check'),'complete-stop','primary full',outstanding(m)>0||!['In progress','Dispatched'].includes(m.status)?'disabled':'')}<p class="helper center">${outstanding(m)>0?'Fund and start the route before recording pickups.':'Confirm quantity and handling at each pickup.'}</p>`:'<p>No delivery route is assigned yet.</p>'}${a(`/mission/${m.id}/dispatch`,'View full route','subtle-link')}</div>`)}
function live(){const m=current();if(!m)return nonprofit();return shell(`${title('LIVE MISSION','Every stop brings us closer.',esc(m.title),badge(m.status,'mint'))}<div class="dispatch-layout"><section class="panel"><h2>Mission timeline</h2><div class="timeline">${m.route.map((s:any,i:number)=>`<div class="${s.completedAt?'done':''}"><span>${s.completedAt?I('check',16):i+1}</span><section><small>${s.completedAt?new Date(s.completedAt).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}):time(s.scheduledTime)}</small><h3>${esc(s.provider)}</h3><p>${s.completedAt?(s.resourceId?'Resources collected':'Delivered to Hope Shelter'):'Awaiting '+(s.resourceId?'pickup':'delivery')}</p></section>${badge(s.completedAt?'Complete':'Pending',s.completedAt?'mint':'')}</div>`).join('')}</div>${m.status==='Completed'?a(`/mission/${m.id}/impact`,'Celebrate your impact '+I('arrow'),'btn primary full'):a(`/volunteer/route/${m.id}`,'Open volunteer route '+I('arrow'),'btn primary full')}</section>${mapPanel(m.route)}</div>`)}
function impactPage(){const m=current();if(!m)return nonprofit();if(m.status!=='Completed')return shell(`${title('MISSION IMPACT','Your impact is still in motion.','Complete the final delivery to record the outcome.')}<section class="panel">${a(`/mission/${m.id}/live`,'Track your mission','btn primary')}</section>`);const x=impact(m),pct=Math.round(m.communityValue/(m.originalCost||1)*100);return shell(`<section class="impact-hero"><span class="impact-medallion">${I('check',48)}</span><span class="eyebrow">MISSION COMPLETE 🎉</span><h1>A mission accomplished.<br>A community connected.</h1><p>${esc(m.title)} · Delivered to Hope Community Shelter</p><blockquote>Your community already had ${pct}%<br>of what this mission needed.</blockquote><div class="actions">${btn('Share Impact '+I('arrow'),'share-impact','primary')}${a('/nonprofit/create','Create Another Mission','btn outline')}</div></section><div class="stats-grid">${stat('people',String(x.peopleServed),'People served')}${stat('leaf',`${x.foodWeight} lbs`,'Estimated food rescued')}${stat('coin',money(x.estimatedValueSaved),'Community resources reused')}${stat('heart',money(x.cashSpent),'Simulated cash contributed')}</div><div class="stats-grid">${stat('mesh',String(x.partners),'Community partners')}${stat('truck','1','Volunteer')}${stat('map',`${x.miles} mi`,'Estimated route distance')}${stat('leaf',`${x.estimatedCO2} lbs`,'Estimated CO₂ avoided')}</div><section class="panel impact-explanation"><h2>Small contributions. A shared outcome.</h2><p>${pct}% of the estimated original mission cost was covered by community resources. Volunteer time: ${x.volunteerHours} hours. Waste and CO₂ are demo estimates (2.25 lb per rescued meal equivalent, 0.9 lb CO₂ per pound), not audited environmental results. ${money(x.cashSpent)} represents simulated funding, not real purchases.</p></section>`)}
function sponsor(){const missions=db.missions.filter((m:Mission)=>m.matches.length&&m.status!=='Completed');return shell(`${title('COMMUNITY SPONSOR','Help a good mission cross the finish line.','See exactly what your contribution makes possible.')}<div class="stats-grid">${stat('heart',money(db.missions.reduce((s:number,m:Mission)=>s+m.contributions.reduce((s,x)=>s+x.amount,0),0)),'Simulated contributions')}${stat('people',String(total('peopleServed')),'People reached')}${stat('check',String(db.impactRecords.length),'Missions completed')}${stat('mesh','61','Local partners')}</div><div class="section-head"><h2>Verified in the demo · remaining gaps</h2>${badge('Simulated payments','lavender')}</div><div class="missions-grid">${missions.map((m:Mission)=>`<section class="panel sponsor-card"><span class="eyebrow">${Math.round(m.communityValue/(m.originalCost||1)*100)}% COMMUNITY COVERED</span><h2>${esc(m.title)}</h2><p>Community resources already contributed ${money(m.communityValue)}.</p><div class="gap-total"><span>Just the remaining gap</span><strong>${money(outstanding(m))}</strong></div><p>${m.requirements[0].category==='meal'?'Additional meal portions and essential supplies':'Missing resource requirements'}</p>${a(`/mission/${m.id}/fund`,'Help complete this mission '+I('arrow'),'btn primary full')}</section>`).join('')||'<div class="empty">No funding gaps yet. Create a mission to see what your community can cover.</div>'}</div>`)}
function explore(){const categories=['All resources','Food','Supplies','Volunteers','Transportation','Space','Funding Needed'];const cat:any={Food:['meal','drink'],Supplies:['supplies'],Volunteers:['transportation'],Transportation:['transportation'],Space:['space']};const items=filter==='Funding Needed'?db.missions.filter((m:Mission)=>outstanding(m)>0&&m.matches.length).map((m:Mission)=>({id:m.id,provider:m.title,name:money(outstanding(m))+' funding needed',category:'funding',quantity:1,unit:'mission',lat:m.lat,lng:m.lng,address:m.address,availableUntil:m.deadline})):db.resources.filter((r:Resource)=>(!cat[filter]||cat[filter].includes(r.category))&&r.status!=='Delivered');return shell(`${title('COMMUNITY RESOURCE MAP','Good is closer than you think.','Explore the resources, people, and possibilities around Atlanta.')}<div class="filter-row">${categories.map(c=>btn(c,'filter-'+c,`chip ${filter===c?'selected':''}`)).join('')}</div><div class="explore-layout"><section>${mapPanel(items)}<p class="helper">Pan and zoom the live map to filter visible resources. When tiles are unavailable, the schematic and complete resource list stay usable.</p></section><section class="explore-list"><div class="section-head"><h3>Nearby resources</h3><span id="resource-count">${items.length} available</span></div><div id="explore-cards">${items.map((r:any)=>r.category==='funding'?a(`/mission/${r.id}/fund`,resourceCard(r)):resourceCard(r)).join('')||'<div class="empty">No resources in this category yet.</div>'}</div></section></div>`,false)}
function globalImpact(){return shell(`${title('COMMUNITY IMPACT','This is what together looks like.','Every shared resource creates a little more possibility.')}<section class="impact-summary"><span class="eyebrow">ATLANTA COMMUNITY · DEMO BASELINE + YOUR MISSIONS</span><h1>Good, multiplied.</h1><p>61 local partners, connected by a common purpose.</p></section><div class="stats-grid">${stat('people',String(2480+total('peopleServed')),'Meals rescued')}${stat('coin',money(18420+total('estimatedValueSaved')),'Resources redirected')}${stat('check',String(142+db.impactRecords.length),'Missions completed')}${stat('leaf',`${8900+total('foodWeight')} lbs`,'Estimated waste prevented')}</div><div class="section-head"><h2>Your completed missions</h2></div><div class="missions-grid">${db.missions.filter((m:Mission)=>m.status==='Completed').map(missionCard).join('')||'<div class="empty">Complete your first mission to see your impact here.</div>'}</div>`)}
function how(){return shell(`${title('HOW MISSIONMESH WORKS','Tell us the outcome.<br>AI assembles the community.','A mission compiler for the resources your community already has.')}<div class="how-list">${[['01','Contribute what you have','Businesses photograph surplus food or post goods, space, and transport. Suggestions are reviewed before anything is listed.','/business/quick-give','Donate surplus'],['02','Describe the outcome','A nonprofit names a goal, deadline, budget, and infrastructure. The demo compiler creates editable requirements.','/nonprofit/create','Create a mission'],['03','Review the community cart','Deterministic matching evaluates categories, distance, quantity, timing, storage, and dietary fit. People approve the final plan.','/nonprofit','View missions'],['04','Fund only what’s missing','Sponsors see the gap and its purpose. Simulated contributions cover what free resources cannot.','/sponsor','See funding gaps'],['05','Deliver and measure','A volunteer follows ordered pickups, confirms each stop, and completes delivery. Everyone sees the outcome.','/volunteer','Volunteer']].map(([n,h,p,url,cta])=>`<section class="panel"><span>${n}</span><div><h2>${h}</h2><p>${p}</p></div>${a(url,cta+' '+I('arrow'),'btn outline')}</section>`).join('')}</div>`)}
function render(){if((path.startsWith('/mission/')||path.startsWith('/volunteer/route/'))&&!current()){path='/not-found'}if(map){map.remove();map=null}let html='';if(current()?.status==='Draft'&&path.startsWith('/mission/')){match(current(),db.resources,db.volunteers[0]);save()}if(path==='/')html=landing();else if(path==='/business')html=business();else if(path==='/business/quick-give')html=quickGive();else if(path==='/nonprofit')html=nonprofit();else if(path==='/nonprofit/create')html=createMission();else if(path==='/volunteer')html=volunteer();else if(path.startsWith('/volunteer/route/'))html=routeView();else if(path==='/sponsor')html=sponsor();else if(path==='/explore')html=explore();else if(path==='/impact')html=globalImpact();else if(path==='/how-it-works')html=how();else if(/^\/mission\/[^/]+\/plan$/.test(path))html=plan();else if(path.endsWith('/fund'))html=funding();else if(path.endsWith('/dispatch'))html=dispatch();else if(path.endsWith('/live'))html=live();else if(path.endsWith('/impact'))html=impactPage();else html=shell(`${title('PAGE NOT FOUND','Let’s get you back to the community.','This page does not exist.',a('/','Return home','btn primary'))}`);$('#app').innerHTML=html;bind();initMap();}
function initMap(){const el=document.getElementById('mission-map');if(!el)return;const L=(window as any).L;if(!L)return;let items=path==='/explore'?db.resources.filter((r:Resource)=>(filter==='All resources'||(filter==='Food'?['meal','drink'].includes(r.category):filter==='Volunteers'||filter==='Transportation'?r.category==='transportation':r.category===filter.toLowerCase()))&&r.status!=='Delivered'):current()?.route||[];if(filter==='Funding Needed'&&path==='/explore')items=db.missions.filter((m:Mission)=>outstanding(m)>0&&m.matches.length).map((m:Mission)=>({...m,provider:m.title,name:money(outstanding(m))+' funding gap'}));if(!items.length)return;try{map=L.map(el,{scrollWheelZoom:false}).setView([33.773,-84.39],13);let loaded=false;const tiles=L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:19}).addTo(map);tiles.on('tileload',()=>loaded=true);setTimeout(()=>{if(!loaded&&map&&document.contains(el)){map.remove();map=null;el.innerHTML=mapPanel(items).match(/<div class="map-fallback">[\s\S]*<\/div><\/div>/)?.[0]?.replace(/<\/div>$/,'')||''}},7000);items.forEach((r:any,i:number)=>L.marker([r.lat,r.lng],{icon:L.divIcon({className:'number-marker',html:`<span>${path==='/explore'?I(r.category==='transportation'?'truck':'box',17):i+1}</span>`,iconSize:[32,32]})}).addTo(map).bindPopup(`<strong>${esc(r.provider)}</strong><br>${esc(r.name)}<br>${esc(r.address)}`));if(path!=='/explore')L.polyline(items.map((r:any)=>[r.lat,r.lng]),{color:'#168361',weight:4,dashArray:'6 6'}).addTo(map);map.fitBounds(L.latLngBounds(items.map((r:any)=>[r.lat,r.lng])).pad(.3));if(path==='/explore')map.on('moveend',()=>{const visible=items.filter((r:any)=>map.getBounds().contains([r.lat,r.lng]));const cards=$('#explore-cards');if(cards)cards.innerHTML=visible.map(resourceCard).join('')||'<div class="empty">No resources in this map area. Zoom out to explore more.</div>';$('#resource-count').textContent=`${visible.length} in view`})}catch{map=null}}
async function processing(messages:string[],done:()=>void){if(busy)return;busy=true;const modal=document.createElement('div');modal.className='processing-overlay';modal.innerHTML=`<div class="processing-card"><div class="spinner">${I('spark',36)}</div><h2 aria-live="polite">${messages[0]}</h2><p>Connecting the possibilities.</p><div class="processing-dots">● ● ●</div></div>`;document.body.append(modal);for(const msg of messages){modal.querySelector('h2')!.textContent=msg;await new Promise(r=>setTimeout(r,550))}modal.remove();busy=false;done()}
function bind(){document.querySelectorAll('[data-nav]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();go((el as HTMLElement).dataset.nav!)}));document.querySelectorAll('[data-role]').forEach(el=>el.addEventListener('click',()=>{role=(el as HTMLElement).dataset.role!;save();go('/'+role.toLowerCase())}));document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>action((el as HTMLElement).dataset.action!)));document.querySelectorAll('[data-item]').forEach(el=>el.addEventListener('change',()=>{const input=el as HTMLInputElement;scan[Number(input.dataset.item)][input.dataset.key!]=input.dataset.key==='quantity'?Number(input.value):input.value}));document.querySelectorAll('[data-remove]').forEach(el=>el.addEventListener('click',()=>{scan.splice(Number((el as HTMLElement).dataset.remove),1);render()}));const file=document.querySelector('#photo') as HTMLInputElement;if(file){file.onchange=()=>readPhoto(file.files?.[0]);const upload=$('.upload');upload.ondragover=e=>{e.preventDefault();upload.classList.add('dragging')};upload.ondrop=e=>{e.preventDefault();readPhoto(e.dataTransfer?.files[0])};}
 document.querySelector('#donation-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target as HTMLFormElement);if(!scan.length||scan.some(x=>!x.name.trim()||!Number.isFinite(x.quantity)||x.quantity<1||!x.unit.trim()))return toast('Confirm a valid name, quantity, and unit for every item.');const until=String(f.get('until')).split(':').map(Number);if(until[0]*60+until[1]<=960)return toast('For this afternoon demo, choose a pickup deadline after 4 PM.');const ids:string[]=[];scan.forEach(x=>{const id=uid();ids.push(id);const r:any={id,organizationId:'org-sunrise',provider:'Sunrise Restaurant',name:x.name,category:x.category,quantity:x.quantity,unit:x.unit,estimatedValue:x.quantity*(x.category==='meal'?8:x.category==='drink'?1.5:2),lat:33.773,lng:-84.38,address:f.get('address'),availableFrom:960,availableUntil:until[0]*60+until[1],storageType:f.get('storage'),dietaryTags:f.getAll('diet'),handlingNotes:f.get('notes'),status:'Available',imageUrl:photo.startsWith('data:')?photo:undefined};if(x.category==='meal'&&/banana/i.test(x.name)){r.category='side';r.estimatedValue=x.quantity*.5}db.resources.push(r)});if(db.demoFlow){db.resources=db.resources.filter((r:Resource)=>r.id!=='sunrise');db.demoFlow=false;}save();photo='';scan=[];scanned=false;go('/business');toast('Your surplus is now available to nearby community missions. Switch to Nonprofit to build your mission.')});
 document.querySelector('#mission-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target as HTMLFormElement);const text=String(f.get('goal')).trim();if(text.length<10)return toast('Describe your outcome with a little more detail.');processing(['Understanding your goal…','Calculating requirements…','Preparing your editable mission…'],()=>{draft=compile(text,{address:f.get('address'),budget:f.get('budget'),deadline:f.get('deadline')});render();$('#requirements')?.scrollIntoView({behavior:'smooth',block:'start'})})});
 document.querySelector('#requirements-form')?.addEventListener('submit',e=>{e.preventDefault();if(!draft)return;const f=new FormData(e.target as HTMLFormElement);draft.title=String(f.get('title'));draft.people=Number(f.get('people'));draft.budget=Number(f.get('budget'));const t=String(f.get('deadline')).split(':').map(Number);draft.deadline=t[0]*60+t[1];draft.address=String(f.get('address'));draft.refrigeration=f.has('fridge');draft.dietaryTags=f.getAll('diet').map(String);draft.requirements.forEach((r,i)=>r.quantity=Number(f.get('quantity-'+i)));const m=draft;processing(['Searching community resources…','Checking availability, storage, and dietary fit…','Assembling your community cart…'],()=>{match(m,db.resources,db.volunteers[0]);const existing=db.missions.findIndex((x:Mission)=>x.id===m.id);if(existing>=0)db.missions[existing]=m;else db.missions.push(m);draft=null;save();go(`/mission/${m.id}/plan`)})});
 document.querySelector('#fund-custom')?.addEventListener('input',e=>{const n=Number((e.target as HTMLInputElement).value);const b=document.querySelector('#fund-form > button');if(b)b.textContent=(n===outstanding(current())?'Fund Full Gap — ':'Contribute ')+money(n)+' (simulated)'});
 document.querySelector('#fund-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target as HTMLFormElement),m=current();const amount=Number(f.get('amount'));if(!Number.isFinite(amount)||amount<=0)return;fund(m,amount,String(f.get('sponsor')));save();render();toast('Simulated funding received. No money was charged.')});
 document.querySelector('#volunteer-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target as HTMLFormElement),v=db.volunteers[0];const min=(s:any)=>Number(s.split(':')[0])*60+Number(s.split(':')[1]);if(min(f.get('until'))<=min(f.get('from')))return toast('Availability end must be after the start.');Object.assign(v,{name:f.get('name'),vehicleType:f.get('vehicle'),capacity:f.get('capacity'),availableFrom:min(f.get('from')),availableUntil:min(f.get('until'))});const r=db.resources.find((r:Resource)=>r.id==='transport');Object.assign(r,{provider:v.name,name:v.vehicleType+' • '+v.capacity+' capacity',availableFrom:v.availableFrom,availableUntil:v.availableUntil});save();toast('Availability saved. Dispatch will verify your time and capacity.')});
 document.querySelector('#assign-volunteer')?.addEventListener('change',e=>{current().manualPickup=(e.target as HTMLSelectElement).value.startsWith('Manual');save()});
}
function readPhoto(file?:File){if(!file)return;if(!file.type.startsWith('image/'))return toast('Choose an image file.');if(file.size>5*1024*1024)return toast('Choose an image smaller than 5 MB.');const reader=new FileReader();reader.onload=()=>{photo=String(reader.result);scanned=false;render();action('scan')};reader.readAsDataURL(file)}
function action(x:string){if(x==='run-demo'||x==='reset'){if(x==='reset'&&!confirm('Reset this browser’s demo missions, donations, and contributions?'))return;db=seed();db.demoFlow=true;role='Business';draft=null;photo='';scanned=false;scan=[];save();go(x==='run-demo'?'/business':'/');toast('Demo reset. Start with Quick Give, then switch to Nonprofit.')}
 else if(x==='sample'){photo='/sample.svg';render();action('scan')}
 else if(x==='scan'){processing(['AI is identifying your surplus…','Estimating quantities conservatively…','Preparing suggestions for your review…'],()=>{scan=[{name:'Boxed meals',quantity:40,unit:'meals',category:'meal'},{name:'Bananas',quantity:30,unit:'pieces',category:'meal'},{name:'Bottled drinks',quantity:24,unit:'bottles',category:'drink'}];scanned=true;render()})}
 else if(x==='edit-mission'){if(current().contributions.length)return;draft=JSON.parse(JSON.stringify(current()));go('/nonprofit/create');$('#requirements')?.scrollIntoView({behavior:'smooth'});}
 else if(x==='add-item'){scan.push({name:'',quantity:1,unit:'items',category:'meal'});render()}
 else if(x.startsWith('example-')){(document.querySelector('#goal') as HTMLTextAreaElement).value=x==='example-food'?example:'Provide school supplies for 40 students by 7 PM. We have $50.'}
 else if(x.startsWith('fund-')){const input=document.querySelector('#fund-custom') as HTMLInputElement;input.value=String(Math.min(Number(x.slice(5)),outstanding(current())));(document.querySelector('#fund-form button[type="submit"]')||document.querySelector('#fund-form > button'))!.textContent='Contribute '+money(Number(input.value))+' (simulated)';input.focus()}
 else if(x==='start-route'){const m=current();if(m.status==='Completed')return go(`/mission/${m.id}/impact`);if(outstanding(m)>0)return toast('Close the funding gap before starting the route.');const v=db.volunteers[0];if(!m.manualPickup&&(v.availableFrom>975||v.availableUntil<m.route.at(-1).scheduledTime||v.capacity==='Small'))return toast('Alex’s availability or capacity does not fit this route. Choose manual pickup or update availability.');const blocked=m.matches.some(x=>{const r=db.resources.find((r:Resource)=>r.id===x.resourceId);return !r||['Collected','Delivered','Pickup Assigned'].includes(r.status)&&r.missionId!==m.id});if(blocked)return toast('A resource is already reserved by another mission. Rebuild the mission to find current resources.');if(!m.manualPickup&&!m.matches.some(x=>x.category==='transportation'))return toast('No volunteer match is available. Choose manual pickup to dispatch.');m.matches.forEach(x=>{const r=db.resources.find((r:Resource)=>r.id===x.resourceId);r.status='Pickup Assigned';r.missionId=m.id});m.status='In progress';save();go(`/volunteer/route/${m.id}`)}
 else if(x==='complete-stop'){const m=current();if(outstanding(m)>0||m.status!=='In progress')return;const s=m.route.find(x=>!x.completedAt);completeStop(m);if(s?.resourceId){const r=db.resources.find((r:Resource)=>r.id===s.resourceId);if(r)r.status='Collected'}if(m.status==='Completed'){m.matches.forEach(x=>{const r=db.resources.find((r:Resource)=>r.id===x.resourceId);r.status='Delivered'});if(!db.impactRecords.some((x:any)=>x.missionId===m.id))db.impactRecords.push(impact(m));save();go(`/mission/${m.id}/impact`);toast('Mission complete. Your community made it happen!')}else{save();render();toast('Pickup confirmed. On to the next stop.')}}
 else if(x==='share-impact'){const m=current(),p=impact(m);const text=`MISSIONMESH: ${p.peopleServed} people served, ${p.foodWeight} lbs of food rescued, ${money(p.estimatedValueSaved)} in community resources reused. ${Math.round(m.communityValue/m.originalCost*100)}% community covered.`;if(navigator.share)navigator.share({title:'Our MissionMesh impact',text}).catch(()=>{});else if(navigator.clipboard)navigator.clipboard.writeText(text).then(()=>toast('Impact copied to clipboard.')).catch(()=>downloadImpact(text));else downloadImpact(text)}
 else if(x.startsWith('filter-')){filter=x.slice(7);render()}
 else if(x==='tab-active'||x==='tab-completed'){const done=x==='tab-completed';$('#mission-list').innerHTML=db.missions.filter((m:Mission)=>(m.status==='Completed')===done).map(missionCard).join('')||`<div class="empty">${done?'Completed missions will appear here.':'Create your first community mission.'}</div>`;document.querySelectorAll('[data-nav]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();go((el as HTMLElement).dataset.nav!)}));document.querySelectorAll('.tabs button').forEach(el=>el.classList.toggle('selected',(el as HTMLElement).dataset.action===x))}
}
function downloadImpact(text:string){const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([text],{type:'text/plain'}));link.download='missionmesh-impact.txt';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast('Impact downloaded.')}
render();
